//! Gold: `word_columns` is 1:1 with the live `harness/electronics/word_columns.py`.
//!
//! `tests/fixtures/gold/word_columns_v1.json` was generated by
//! `scripts/gold_word_columns.py` — `extract` cases carry page word lists
//! (`get_text("words")` 5-tuples) and run `extract_pin_columns` end to end
//! (the generator monkeypatched `_load_words` to replay them, including the
//! continuation lookback); `select`/`bogey`/`capability` cases call the pure
//! readers. Word geometry is PDF-layer: the port consumes the same
//! `(x0, y0, x1, y1, text)` tuples.
//!
//! The cases pin the traps the extractor exists for: identifiers assigned to
//! package columns by x-overlap with printed headers, names matched within
//! the row band and joined across runs, the two-row minimum and bare `Pin`
//! headers demanding pure numbers, continuation pages reusing a prior page's
//! header band, two-group tables extracting side-by-side and merging on
//! generic selection, `column_key`'s Python banker's rounding, and
//! `package_pin_bogey`'s `family+extra` counting.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::word_columns::{
    capability_result, extract_pin_columns, package_pin_bogey, pipeline, select_package_columns,
    PackageColumn, PinRowClaim, Word,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/word_columns_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn words_of(v: &Value) -> Vec<Word> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|w| {
            (
                w[0].as_f64().unwrap(),
                w[1].as_f64().unwrap(),
                w[2].as_f64().unwrap(),
                w[3].as_f64().unwrap(),
                w[4].as_str().unwrap().to_string(),
            )
        })
        .collect()
}

fn span_json(span: &(String, (f64, f64, f64, f64))) -> Value {
    serde_json::json!({
        "text": span.0,
        "bbox": [span.1 .0, span.1 .1, span.1 .2, span.1 .3],
    })
}

fn column_json(column: &PackageColumn) -> Value {
    serde_json::json!({
        "header": column.header,
        "column_key": column.column_key,
        "header_span": span_json(&column.header_span),
        "rows": column
            .rows
            .iter()
            .map(|row: &PinRowClaim| serde_json::json!({
                "pin_no": row.pin_no,
                "name": row.name,
                "identifier_span": span_json(&row.identifier_span),
                "name_span": span_json(&row.name_span),
            }))
            .collect::<Vec<_>>(),
    })
}

fn columns_json(columns: &dw_recon::word_columns::Columns) -> Value {
    // The reference's expected is a dict keyed by column_key; serde_json's
    // Map is sorted, so key order is irrelevant to equality.
    let mut map = serde_json::Map::new();
    for (key, column) in columns {
        map.insert(key.clone(), column_json(column));
    }
    Value::Object(map)
}

fn columns_from(v: &Value, order: Option<&Value>) -> dw_recon::word_columns::Columns {
    // The gold wire sorts dict keys, so insertion order travels separately.
    let mut out = dw_recon::word_columns::Columns::new();
    let keys: Vec<String> = match order {
        Some(list) => list
            .as_array()
            .unwrap()
            .iter()
            .map(|k| k.as_str().unwrap().to_string())
            .collect(),
        None => v.as_object().unwrap().keys().cloned().collect(),
    };
    for key in keys {
        let column = &v[&key];
        let rows = column["rows"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| PinRowClaim {
                pin_no: row["pin_no"].as_str().unwrap().to_string(),
                name: row["name"].as_str().unwrap().to_string(),
                identifier_span: span_from(&row["identifier_span"]),
                name_span: span_from(&row["name_span"]),
            })
            .collect();
        out.push_back((
            key.clone(),
            PackageColumn {
                header: column["header"].as_str().unwrap().to_string(),
                column_key: column["column_key"].as_str().unwrap().to_string(),
                header_span: span_from(&column["header_span"]),
                rows,
            },
        ));
    }
    out
}

fn span_from(v: &Value) -> (String, (f64, f64, f64, f64)) {
    (
        v["text"].as_str().unwrap().to_string(),
        (
            v["bbox"][0].as_f64().unwrap(),
            v["bbox"][1].as_f64().unwrap(),
            v["bbox"][2].as_f64().unwrap(),
            v["bbox"][3].as_f64().unwrap(),
        ),
    )
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "extract" => {
                let pages: Vec<Vec<Word>> = case["input"]["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(words_of)
                    .collect();
                let page_1based = case["input"]["page_1based"].as_i64().unwrap();
                let columns = extract_pin_columns(page_1based, |page| {
                    let index = usize::try_from(page).ok()?;
                    if index < 1 || index > pages.len() {
                        None
                    } else {
                        Some(pages[index - 1].clone())
                    }
                });
                assert_eq!(columns_json(&columns), case["expected"], "case {name}");
            }
            "select" => {
                let columns = columns_from(
                    &case["input"]["columns"],
                    Some(&case["input"]["column_order"]),
                );
                // The generic-merge fallback preserves the reference's
                // insertion order.
                let selected = select_package_columns(
                    &columns,
                    case["input"]["requested_package"].as_str().unwrap(),
                );
                let expected: Vec<Value> = selected.iter().map(column_json).collect();
                assert_eq!(
                    serde_json::to_value(expected).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "bogey" => {
                let got = package_pin_bogey(case["input"]["token"].as_str().unwrap());
                let expected: Option<(i64, i64)> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "capability" => {
                let columns =
                    columns_from(&serde_json::json!({ "x": case["input"]["column"] }), None);
                let column = &columns.front().unwrap().1;
                assert_eq!(capability_result(column), case["expected"], "case {name}");
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
    // The pipeline is also exercised directly: `select` columns were
    // produced by `_pipeline` in the generator.
    let _ = pipeline;
}
